package help

import (
	"github.com/MateusMoutinhoOrg/Agnos/sandbox/api"
)

// NewCommand builds this command's declaration — the whole of what its
// entries.yaml says — and closes CommandHandler over the sandbox as the
// handler behind it. It is called once, by sandbox/binds/cli.go, and what it
// returns is one entry of sandbox.Commands.
// Generated by `agnos build` — do not edit by hand; the logic
// lives in handler.go.
func NewCommand(sandbox *api.Sandbox) *api.Command {
	command := api.NewCommand()

	command.Name = "help"
	command.Identifiers = []string{"help", "--help"}
	command.Category = "Info"
	command.Help = "Display help for a command"
	command.LongDescription = "When called without arguments, lists every available command\ngrouped by category. When called with a command name, shows\ndetailed usage, arguments, flags, and examples for that command.\n"
	command.Examples = []string{"help", "help start"}
	command.Hidden = false

	command.Flags = []api.CommandFlag{}

	command.Args = []api.CommandArg{
		{
			Id:          "command",
			Type:        "string",
			Required:    false,
			Array:       false,
			Description: "The command to describe; omit it to list every command",
			Examples:    []string{"help start"},
			Default:     "",
			HasDefault:  false,
		},
	}

	command.Handler = func() int {
		return CommandHandler(sandbox, command)
	}

	return command
}
